import { A, adminReady, slot, unlockSheet } from '../../features/admin.js';
import { S } from '../../state.js';
import { joinInput } from '../sheets/cloud.js';
import { $, app, html, setHtml } from '../util.js';

const iosTab = (/iP(hone|ad|od)/.test(navigator.userAgent) || (/Macintosh/.test(navigator.userAgent) && navigator.maxTouchPoints > 1)) && !navigator.standalone && !matchMedia('(display-mode: standalone)').matches;

const DOLPHIN = html`<svg viewBox="0 0 156 124" aria-hidden="true"><g fill="#fff" stroke="#fff" stroke-width="14" stroke-linejoin="round"><path d="M18 76C14 42 44 22 82 28 112 33 130 54 132 80 116 76 108 88 86 92 58 96 26 98 18 76Z"/><path d="M130 74C140 62 146 60 148 50 138 52 132 60 128 68ZM130 80C142 82 148 92 144 102 134 98 130 90 128 84Z"/></g><g stroke="#7A5A52" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"><path d="M78 29C80 10 94 8 100 14 92 17 90 24 92 32Z" fill="#7CCBF0"/><path d="M130 74C140 62 146 60 148 50 138 52 132 60 128 68ZM130 80C142 82 148 92 144 102 134 98 130 90 128 84Z" fill="#7CCBF0"/><path d="M18 76C14 42 44 22 82 28 112 33 130 54 132 80 116 76 108 88 86 92 58 96 26 98 18 76Z" fill="#9ADCF8"/><path d="M34 82C54 94 84 94 114 84 102 98 58 104 34 82Z" fill="#fff" stroke="none"/><path d="M70 80C60 94 70 104 82 100 86 92 82 86 80 82Z" fill="#7CCBF0"/><path d="M38 36C40 16 74 16 78 36Z" fill="#FFE48A"/><path d="M26 38C40 28 76 26 90 38 76 44 40 44 26 38Z" fill="#FFE48A"/><path d="M40 33H76" stroke="#FFB7D5" stroke-width="5"/></g><circle cx="48" cy="58" r="5.5" fill="#5A4440"/><circle cx="49.8" cy="56" r="1.8" fill="#fff"/><ellipse cx="36" cy="68" rx="7.5" ry="4.5" fill="#FFB7D5" opacity=".9"/><path d="M22 70Q32 80 46 72" fill="none" stroke="#5A4440" stroke-width="3" stroke-linecap="round"/></svg>`;
const SHAPES = html`<circle cx="42" cy="58" r="24"/><circle cx="74" cy="40" r="32"/><circle cx="112" cy="52" r="26"/><circle cx="134" cy="66" r="16"/><circle cx="24" cy="68" r="14"/><rect x="24" y="58" width="112" height="26" rx="13"/>`;
const FACE = html`<circle cx="62" cy="62" r="3" fill="#5A4440"/><circle cx="88" cy="62" r="3" fill="#5A4440"/><ellipse cx="54" cy="70" rx="6" ry="4" fill="#FFB7D5" opacity=".85"/><ellipse cx="96" cy="70" rx="6" ry="4" fill="#FFB7D5" opacity=".85"/><path d="M69 68Q75 75 81 68" fill="none" stroke="#5A4440" stroke-width="2.4" stroke-linecap="round"/>`;
const cloud = (n, cls, face) => html`<svg class="cv-cl ${cls}" viewBox="0 0 160 96" aria-hidden="true"><defs><linearGradient id="cvg${n}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff"/><stop offset="1" stop-color="#E4F4FF"/></linearGradient></defs><g fill="#BFE3F8" transform="translate(0 5)">${SHAPES}</g><g fill="url(#cvg${n})">${SHAPES}</g><ellipse cx="70" cy="26" rx="22" ry="7" fill="#fff" opacity=".9"/>${face ? FACE : ''}</svg>`;
const sparkle = (x, y, w) => html`<svg class="cv-sp" style="left:${x}px;top:${y}px;width:${w}px" viewBox="0 0 20 20" aria-hidden="true"><path d="M10 0 12 8 20 10 12 12 10 20 8 12 0 10 8 8Z" fill="#fff"/></svg>`;

export function renderWelcome() {
  setHtml($('#nav'), '');
  setHtml(app, html`<div class="welcome cv"><div class="cv-sky" aria-hidden="true"><div class="in"><svg class="cv-trail" viewBox="0 0 420 96"><path d="M-30 78C70 10 170 82 270 30S400 8 450 22"/></svg><span class="cv-plane" data-k="1">✈️</span></div>${cloud(1, 'c1', true)}${cloud(2, 'c2', false)}${sparkle(152, 20, 14)}${sparkle(258, 70, 10)}${sparkle(334, 18, 12)}${sparkle(60, 74, 9)}</div><p class="cv-brand">TRAVEL LEDGER</p><h1 class="cv-h1">一起出發吧！</h1><p class="cv-sub">輸入邀請碼，加入旅程</p><div class="cv-stage"><div class="cv-mascot" id="logo" role="img" aria-label="Travel Ledger">${DOLPHIN}</div><div class="cv-bub">歡迎登機～</div></div><div class="cv-wrap"><i class="cv-tape t1"></i><i class="cv-tape t2"></i><div class="cv-stamp" aria-hidden="true">WELCOME<br>${new Date().getFullYear()}</div><div class="cv-pass"><div class="cv-ph"><span>BOARDING PASS</span><b aria-hidden="true">✈️</b></div><label class="cv-lb" for="wc">邀請碼或同步碼</label><input id="wc" class="cv-in" placeholder="XXXXX-XXXXX" autocomplete="off" autocapitalize="characters" autocorrect="off" spellcheck="false"><div class="cv-perf"></div><button class="cv-go" id="wgo">加入旅程</button></div></div><p class="cv-lock">🔒 只有受邀的旅伴看得到</p>${iosTab ? html`<p class="cv-note">📲 iPhone 請先「加入主畫面」，再從主畫面圖示打開並輸入邀請碼。邀請碼只能用一次、只給一支手機。</p>` : ''}${S.adm ? slot('welcome') : ''}<div class="cv-floor" aria-hidden="true">${cloud(3, 'c3', false)}${cloud(4, 'c4', false)}</div></div>`);
  $('#logo').onclick = () => { S.hid = (S.hid || 0) + 1; clearTimeout(S.hidT); S.hidT = setTimeout(() => { S.hid = 0; }, 3000); if (S.hid >= 5 && !S.adm) { const open = () => { S.adm = true; renderWelcome(); }; adminReady() ? open() : unlockSheet(open); } };
  const plane = $('.cv-plane'), go = () => { const v = $('#wc').value; if (v.trim()) plane.dataset.k = plane.dataset.k === '1' ? '2' : '1'; joinInput(v); };
  $('#wgo').onclick = go; $('#wc').onkeydown = e => { if (e.key === 'Enter' && !e.isComposing) go(); };
  if (S.adm) A.bindWelcome?.();
}
